select count(*)::int as applied_count, count(*) filter(where disposition<>'COMPARABLE' or group_code not in ('A','B','C','D','E','F','G'))::int as invalid_count from fitmatch_catalog.source_category_comparison_groups where policy_version='retailer-comparison-groups-v3-seven-20260911' and mapping_basis='RETAILER_API_CATEGORY_AUDIT_APPROVED_20260916';
select source_code,group_code,count(*)::int from fitmatch_catalog.source_category_comparison_groups where policy_version='retailer-comparison-groups-v3-seven-20260911' and mapping_basis='RETAILER_API_CATEGORY_AUDIT_APPROVED_20260916' group by source_code,group_code order by source_code,group_code;
